import os
import sqlite3
import hashlib
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/data/app.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        password_hash TEXT,
        role TEXT DEFAULT 'user',
        email TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        details TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    # seed admin
    admin_hash = hashlib.sha256(b'admin_secret_2024').hexdigest()
    db.execute("INSERT OR IGNORE INTO users (username, password_hash, role, email) VALUES ('admin', ?, 'admin', 'admin@corp.internal')", (admin_hash,))
    db.execute("INSERT OR IGNORE INTO users (username, password_hash, role, email) VALUES ('alice', ?, 'user', 'alice@corp.internal')", (hashlib.sha256(b'alice123').hexdigest(),))
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('value', '')

    # Basic field validation - only allow searching certain columns
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid search field'}), 400

    # Log the search for compliance
    db = get_db()
    db.execute("INSERT INTO audit_log (action, details) VALUES ('search', ?)",
               (f"field={field}, value={value}",))
    db.commit()

    # Construct query with validated field name but user-supplied value
    query = f"SELECT username, email, role FROM users WHERE {field} LIKE '%{value}%'"

    try:
        results = db.execute(query).fetchall()
        return jsonify({'results': [dict(r) for r in results]})
    except Exception as e:
        return jsonify({'error': 'Search failed', 'detail': str(e)}), 500

@app.route('/api/users/profile', methods=['GET'])
def get_profile():
    """Get user profile by ID - uses parameterized query"""
    user_id = request.args.get('id')
    if not user_id:
        return jsonify({'error': 'Missing id parameter'}), 400
    db = get_db()
    result = db.execute("SELECT username, email, role FROM users WHERE id = ?", (user_id,)).fetchone()
    if result:
        return jsonify(dict(result))
    return jsonify({'error': 'User not found'}), 404

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy', 'version': '2.1.3'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
